  tool_magnet_link_decoder_article:
    'Examina un URI magnet sin abrir un cliente torrent. El parser conserva parámetros repetidos, reconoce temas exactos de BitTorrent v1 y v2, comprueba trackers y tamaños, y mantiene visibles los valores dañados junto a sus avisos.',
  tool_magnet_link_decoder_clear: 'Limpiar',
  tool_magnet_link_decoder_copy_done: 'Copiado',
  tool_magnet_link_decoder_copy_hash: 'Copiar info hash',
  tool_magnet_link_decoder_copy_json: 'Copiar JSON',
